using System;using System.Collections.Generic;using System.Text.Json;
public static class ConsumerTests32 {
 static readonly List<string> passed=new List<string>();static void Check(bool b,string s){if(!b)throw new Exception(s);passed.Add(s);}
 static void Reject(Action a,string s){bool bad=false;try{a();}catch(ArgumentException){bad=true;}catch(InvalidOperationException){bad=true;}Check(bad,s);}
 public static void Main(){
  var producer=new Submission31("producer/frame99",1);producer.BeforeCommands();producer.StageRecorded(1);producer.StageRecorded(2);producer.StageRecorded(4);producer.StageRecorded(8);producer.BeforeBarrier();producer.AcceptCallback("producer/frame99",1,true,false);
  var c=new ConsumerReads32();var t=c.Begin(16);Check(producer.CanRelease&&!c.CanRelease,"producer completion alone does not release a later consumer");Reject(()=>c.Begin(16),"only one bounded consumer may be in flight");c.Complete(t,true,false,16);Check(c.CanRelease&&!c.HasError,"successful consumer completion releases its own lease");
  var t2=c.Begin(32);c.Complete(t,true,false,16);Check(!c.CanRelease&&c.HasError,"previous request callback cannot release next consumer");c.Complete(t2,true,false,32);Check(c.CanRelease&&c.HasError,"valid drain can finish after foreign callback but output stays invalid");Reject(()=>c.Begin(16),"failed owner cannot restart observation");
  var pending=new ConsumerReads32();var p=pending.Begin(64);pending.Seal();Check(!pending.CanRelease,"normal exit seals new reads without releasing pending consumer");Reject(()=>pending.Begin(16),"sealed observer cannot append another read");pending.Complete(p,true,false,64);Check(pending.CanRelease,"late successful callback permits drain after exit");
  var err=new ConsumerReads32();var e=err.Begin(16);err.Complete(e,true,true,16);Check(!err.CanRelease&&err.HasError,"error callback does not prove consumer release");Reject(()=>err.Begin(16),"error does not automatically retry consumer request");
  err.Complete(e,true,false,16);Check(!err.CanRelease,"duplicate corrected callback cannot replace a failed receipt");
  var count=new ConsumerReads32();var q=count.Begin(16);count.Complete(q,true,false,32);Check(!count.CanRelease&&count.HasError,"mismatched byte count cannot release consumer");
  var partial=new ConsumerReads32();var v=partial.Begin(16);partial.Complete(v,false,false,16);Check(!partial.CanRelease&&partial.HasError,"pending is not a successful completion");
  var api=new ConsumerReads32();api.Begin(16);api.Fail();Check(!api.CanRelease,"enqueue exception retains uncertain consumer");
  var copyFail=new ConsumerReads32();var copy=copyFail.Begin(16);copyFail.Fail();copyFail.Complete(copy,true,false,16);Check(copyFail.CanRelease&&copyFail.HasError,"CPU file/copy failure invalidates output but known GPU completion permits release");
  var idle=new ConsumerReads32();idle.Seal();Check(idle.CanRelease,"cancel before any consumer needs no GPU acknowledgement");
  var other=new ConsumerReads32();var foreign=other.Begin(16);var victim=new ConsumerReads32();var own=victim.Begin(16);victim.Complete(foreign,true,false,16);Check(!other.CanRelease&&!victim.CanRelease&&victim.HasError,"another book token cannot release a same-size consumer");victim.Complete(own,true,false,16);Check(victim.CanRelease&&!other.CanRelease,"independent producer/view consumer books drain independently");
  var exit=new ExitCoordinator31();int exits=0,releases=0,restores=0;var read=new ConsumerReads32();var token=read.Begin(16);exit.Begin(()=>read.Seal(),()=>{},()=>exits++);exit.Pump(true,()=>producer.CanRelease&&read.CanRelease,()=>releases++,()=>restores++);Check(exits==1&&restores==1&&releases==0,"normal exit/Edit restore proceed while consumer resources stay retained");read.Complete(token,true,false,16);exit.Pump(true,()=>producer.CanRelease&&read.CanRelease,()=>releases++,()=>restores++);Check(exit.Finished&&releases==1&&restores==1,"same original Exit coordinator drains after consumer completion");
  Check(ConsumerReads32.ColourBytes(0,0,480,32,480,272)==245760,"existing32-row colour strip stays within bound");Check(ConsumerReads32.ColourBytes(143,63,1,1,144,64)==16,"last single-pixel ROI has exact byte count");
  Reject(()=>ConsumerReads32.ColourBytes(0,0,480,64,480,272),"large colour strip rejected before submission");Reject(()=>ConsumerReads32.ColourBytes(1,0,Int32.MaxValue,1,480,272),"overflowing rectangle rejected");Reject(()=>ConsumerReads32.ColourBytes(-1,0,1,1,480,272),"negative rectangle rejected");Reject(()=>new ConsumerReads32().Begin(0),"zero byte request rejected");
  Reject(()=>ConsumerReads32.ColourBytes(0,0,1<<30,1<<30,1<<30,1<<30),"pixel budget checked before byte multiplication can overflow");
  var request=new EditorExitRequest32();int begins=0;bool workerRejected=false;var worker=new System.Threading.Thread(()=>{request.Request();try{request.Drain(()=>begins++);}catch(InvalidOperationException){workerRejected=true;}});worker.Start();worker.Join();Check(request.Requested&&workerRejected&&begins==0,"worker callback only queues exit and cannot invoke Editor actions");request.Drain(()=>begins++);request.Request();request.Drain(()=>begins++);Check(begins==1,"creating observer thread drains normal exit exactly once");
  Console.WriteLine(JsonSerializer.Serialize(new{checks=passed.Count,passed,UnityGPUCalls=0,actualConsumerReadbackObserved=false}));
 }
}
